//! Conversion between Unicode text and the Vietnamese charsets Unikey supports.
//!
//! Every conversion goes through Unikey's 213-entry "standard Vietnamese
//! character set" (see `standard.rs`), so any charset converts to any other.
//! Tables come from Unikey's `data.cpp` (Pham Kim Long, GPL-2.0-or-later) and
//! are generated by `tools/generate_tables.py`.
//!
//! Text outside the standard set (digits, punctuation, other scripts) passes
//! through where the charset can hold it; a single-byte charset writes `#`
//! for what it cannot.

#![forbid(unsafe_code)]

mod byte_codec;
mod standard;
mod tables;
mod unicode_codec;
mod viqr;

#[cfg(test)]
mod tests;

use byte_codec::{SingleByteCodec, TwoByteCodec};
use standard::{Glyph, glyphs_from_text, text_from_glyphs};
use tables as t;

/// A Vietnamese text encoding.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Charset {
    /// UTF-16 little endian, precomposed letters.
    Unicode,
    /// UTF-16 little endian, letter followed by a combining tone mark ("UNI-COMP").
    UnicodeDecomposed,
    Utf8,
    /// Unikey's x-utf8: the same bytes as UTF-8, counted in characters when deleting.
    XUtf8,
    /// `&#7879;` references, ASCII literal.
    NcrDecimal,
    /// `&#x1EC7;` references; U+0080..U+00FF are raw bytes.
    NcrHexadecimal,
    /// `\x1EC7` escapes as used in C string literals.
    CString,
    WindowsCp1258,
    Viqr,
    /// UTF-8 text that may also contain VIQR sequences.
    Utf8Viqr,
    Tcvn3,
    Vps,
    Viscii,
    BkHcm1,
    VietwareF,
    Isc,
    VniWindows,
    BkHcm2,
    VietwareX,
    VniMac,
}

impl Charset {
    pub const ALL: [Charset; 20] = [
        Charset::Unicode,
        Charset::UnicodeDecomposed,
        Charset::Utf8,
        Charset::XUtf8,
        Charset::NcrDecimal,
        Charset::NcrHexadecimal,
        Charset::CString,
        Charset::WindowsCp1258,
        Charset::Viqr,
        Charset::Utf8Viqr,
        Charset::Tcvn3,
        Charset::Vps,
        Charset::Viscii,
        Charset::BkHcm1,
        Charset::VietwareF,
        Charset::Isc,
        Charset::VniWindows,
        Charset::BkHcm2,
        Charset::VietwareX,
        Charset::VniMac,
    ];

    /// Canonical name, as Unikey's command line spells it where it has one.
    pub fn name(self) -> &'static str {
        match self {
            Charset::Unicode => "UNICODE",
            Charset::UnicodeDecomposed => "UNI-COMP",
            Charset::Utf8 => "UTF-8",
            Charset::XUtf8 => "X-UTF-8",
            Charset::NcrDecimal => "NCR-DEC",
            Charset::NcrHexadecimal => "NCR-HEX",
            Charset::CString => "C-STRING",
            Charset::WindowsCp1258 => "WINCP-1258",
            Charset::Viqr => "VIQR",
            Charset::Utf8Viqr => "UVIQR",
            Charset::Tcvn3 => "TCVN3",
            Charset::Vps => "VPS",
            Charset::Viscii => "VISCII",
            Charset::BkHcm1 => "BKHCM1",
            Charset::VietwareF => "VIETWARE-F",
            Charset::Isc => "ISC",
            Charset::VniWindows => "VNI-WIN",
            Charset::BkHcm2 => "BKHCM2",
            Charset::VietwareX => "VIETWARE-X",
            Charset::VniMac => "VNI-MAC",
        }
    }

    /// Looks a charset up by name, ignoring case. Accepts `UTF8` for `UTF-8`.
    pub fn from_name(name: &str) -> Option<Charset> {
        if name.eq_ignore_ascii_case("UTF8") {
            return Some(Charset::Utf8);
        }
        Charset::ALL
            .into_iter()
            .find(|charset| charset.name().eq_ignore_ascii_case(name))
    }

    /// How many deletions undo `text` written in this charset. Unicode and
    /// x-utf8 apps delete by character; legacy apps by byte; "UNI-COMP" by
    /// UTF-16 unit.
    pub fn deletions_for(self, text: &str) -> usize {
        match self {
            Charset::Unicode | Charset::XUtf8 => text.chars().count(),
            Charset::UnicodeDecomposed => encode(text, self).len() / 2,
            _ => encode(text, self).len(),
        }
    }
}

/// Encodes Unicode text. Precomposed and combining-mark input both work.
pub fn encode(text: &str, charset: Charset) -> Vec<u8> {
    encode_glyphs(&glyphs_from_text(text), charset)
}

/// Decodes bytes into NFC text (Unikey's precomposed form). Invalid input
/// becomes U+FFFD; bytes the charset does not assign pass through as Latin-1.
pub fn decode(bytes: &[u8], charset: Charset) -> String {
    text_from_glyphs(&decode_glyphs(bytes, charset))
}

/// Converts between two charsets without going through a `String`.
pub fn convert(bytes: &[u8], from: Charset, to: Charset) -> Vec<u8> {
    encode_glyphs(&decode_glyphs(bytes, from), to)
}

fn encode_glyphs(glyphs: &[Glyph], charset: Charset) -> Vec<u8> {
    match charset {
        Charset::Unicode => unicode_codec::encode_utf16_little_endian(glyphs),
        Charset::UnicodeDecomposed => unicode_codec::encode_utf16_decomposed(glyphs),
        Charset::Utf8 | Charset::XUtf8 => unicode_codec::encode_utf8(glyphs),
        Charset::NcrDecimal => unicode_codec::encode_decimal_references(glyphs),
        Charset::NcrHexadecimal => unicode_codec::encode_hexadecimal_references(glyphs),
        Charset::CString => unicode_codec::encode_c_string(glyphs),
        Charset::WindowsCp1258 => windows_cp1258_codec().encode(glyphs),
        Charset::Viqr | Charset::Utf8Viqr => viqr::encode_viqr(glyphs),
        Charset::Tcvn3 => SingleByteCodec::new(&t::SINGLE_BYTE_TCVN3).encode(glyphs),
        Charset::Vps => SingleByteCodec::new(&t::SINGLE_BYTE_VPS).encode(glyphs),
        Charset::Viscii => SingleByteCodec::new(&t::SINGLE_BYTE_VISCII).encode(glyphs),
        Charset::BkHcm1 => SingleByteCodec::new(&t::SINGLE_BYTE_BK_HCM_1).encode(glyphs),
        Charset::VietwareF => SingleByteCodec::new(&t::SINGLE_BYTE_VIETWARE_F).encode(glyphs),
        Charset::Isc => SingleByteCodec::new(&t::SINGLE_BYTE_ISC).encode(glyphs),
        Charset::VniWindows => TwoByteCodec::new(&t::DOUBLE_BYTE_VNI_WINDOWS).encode(glyphs),
        Charset::BkHcm2 => TwoByteCodec::new(&t::DOUBLE_BYTE_BK_HCM_2).encode(glyphs),
        Charset::VietwareX => TwoByteCodec::new(&t::DOUBLE_BYTE_VIETWARE_X).encode(glyphs),
        Charset::VniMac => TwoByteCodec::new(&t::DOUBLE_BYTE_VNI_MAC).encode(glyphs),
    }
}

fn decode_glyphs(bytes: &[u8], charset: Charset) -> Vec<Glyph> {
    match charset {
        Charset::Unicode | Charset::UnicodeDecomposed => {
            unicode_codec::decode_utf16_little_endian(bytes)
        }
        Charset::Utf8 | Charset::XUtf8 => unicode_codec::decode_utf8(bytes),
        Charset::NcrDecimal | Charset::NcrHexadecimal => unicode_codec::decode_references(bytes),
        Charset::CString => unicode_codec::decode_c_string(bytes),
        Charset::WindowsCp1258 => windows_cp1258_codec().decode(bytes),
        Charset::Viqr => viqr::decode_viqr(bytes),
        Charset::Utf8Viqr => viqr::decode_utf8_viqr(bytes),
        Charset::Tcvn3 => SingleByteCodec::new(&t::SINGLE_BYTE_TCVN3).decode(bytes),
        Charset::Vps => SingleByteCodec::new(&t::SINGLE_BYTE_VPS).decode(bytes),
        Charset::Viscii => SingleByteCodec::new(&t::SINGLE_BYTE_VISCII).decode(bytes),
        Charset::BkHcm1 => SingleByteCodec::new(&t::SINGLE_BYTE_BK_HCM_1).decode(bytes),
        Charset::VietwareF => SingleByteCodec::new(&t::SINGLE_BYTE_VIETWARE_F).decode(bytes),
        Charset::Isc => SingleByteCodec::new(&t::SINGLE_BYTE_ISC).decode(bytes),
        Charset::VniWindows => TwoByteCodec::new(&t::DOUBLE_BYTE_VNI_WINDOWS).decode(bytes),
        Charset::BkHcm2 => TwoByteCodec::new(&t::DOUBLE_BYTE_BK_HCM_2).decode(bytes),
        Charset::VietwareX => TwoByteCodec::new(&t::DOUBLE_BYTE_VIETWARE_X).decode(bytes),
        Charset::VniMac => TwoByteCodec::new(&t::DOUBLE_BYTE_VNI_MAC).decode(bytes),
    }
}

/// CP-1258 writes composite letters but also reads the precomposed ones.
fn windows_cp1258_codec() -> TwoByteCodec {
    TwoByteCodec::with_extra_input_tables(&t::WIN_CP1258_COMPOSITE, &[&t::WIN_CP1258_PRECOMPOSED])
}

/// Joins letters and combining tone marks into precomposed Vietnamese letters.
pub fn normalize_to_precomposed(text: &str) -> String {
    text_from_glyphs(&glyphs_from_text(text))
}
